mod "surveybeat_cloudflare_compliance" {
  title         = "SurveyBeat Cloudflare GDPR & SOC 2 Compliance"
  description   = "Custom Powerpipe compliance benchmarks using Steampipe turbot/cloudflare to verify GDPR and SOC 2 controls across SurveyBeat's Cloudflare infrastructure."
  color         = "#F38020"
  documentation = file("./README.md")

  require {
    powerpipe {
      min_version = "1.0.0"
    }

    plugin "cloudflare" {
      min_version = "1.6.0"
    }
  }
}

locals {
  common_tags = {
    service = "Cloudflare"
    product = "SurveyBeat"
  }
}

benchmark "all_compliance" {
  title       = "SurveyBeat Cloudflare Compliance (GDPR & SOC 2)"
  description = "Runs both GDPR and SOC 2 compliance benchmarks against SurveyBeat's Cloudflare account, zones, DNS, Workers, Access, and logging configuration."

  children = [
    benchmark.gdpr,
    benchmark.soc2
  ]

  tags = merge(local.common_tags, {
    type = "Benchmark"
  })
}

benchmark "gdpr" {
  title       = "GDPR (Cloudflare Infrastructure Controls)"
  description = "GDPR technical and organizational measures (Art. 5, 25, 32, 33) verified against Cloudflare via Steampipe turbot/cloudflare, aligned with SurveyBeat SPEC §5.3 & §7."

  children = [
    benchmark.gdpr_privacy_by_design,
    benchmark.gdpr_security_of_processing,
    benchmark.gdpr_audit_and_monitoring
  ]

  tags = merge(local.common_tags, {
    framework = "gdpr"
    type      = "Benchmark"
  })
}

benchmark "gdpr_privacy_by_design" {
  title       = "Articles 5 & 25: Data Minimization and Privacy by Design"
  description = "Ensures SurveyBeat's anonymous Submission Worker and Logpush pipelines do not retain or export identifying request telemetry."

  children = [
    control.submission_worker_no_logpush,
    control.submission_worker_no_tail_consumers,
    control.logpush_no_unfiltered_submission_pii
  ]

  tags = merge(local.common_tags, {
    framework = "gdpr"
    article   = "art_5_art_25"
  })
}

benchmark "gdpr_security_of_processing" {
  title       = "Article 32: Security of Processing"
  description = "Ensures strong encryption in transit, edge WAF protection, DNS integrity, email authentication, and strong operator access controls."

  children = [
    control.zone_ssl_strict,
    control.zone_min_tls_version,
    control.zone_tls_1_3_enabled,
    control.zone_always_use_https,
    control.zone_automatic_https_rewrites,
    control.zone_hsts_enabled,
    control.zone_waf_enabled,
    control.zone_dnssec_enabled,
    control.dns_email_auth_records,
    control.dns_sensitive_records_proxied,
    control.account_enforce_twofactor,
    control.user_mfa_enabled,
    control.api_token_expiration_set,
    control.access_policy_no_unrestricted_bypass,
    control.r2_bucket_inventory_encryption
  ]

  tags = merge(local.common_tags, {
    framework = "gdpr"
    article   = "art_32"
  })
}

benchmark "gdpr_audit_and_monitoring" {
  title       = "Article 33: Auditability and Incident Detection"
  description = "Verifies audit logging and account incident notification policies are active."

  children = [
    control.account_notification_policy_configured,
    control.audit_log_active
  ]

  tags = merge(local.common_tags, {
    framework = "gdpr"
    article   = "art_33"
  })
}

benchmark "soc2" {
  title       = "SOC 2 Trust Services Criteria (Cloudflare)"
  description = "SOC 2 Security (CC6, CC7, CC8) and Availability (A1) checks for SurveyBeat's Cloudflare account, zones, DNS, Workers, and Access configuration."

  children = [
    benchmark.soc2_cc6_logical_access,
    benchmark.soc2_cc6_boundary_and_transmission,
    benchmark.soc2_cc7_cc8_monitoring_and_change,
    benchmark.soc2_a1_availability_and_storage
  ]

  tags = merge(local.common_tags, {
    framework = "soc2"
    type      = "Benchmark"
  })
}

benchmark "soc2_cc6_logical_access" {
  title       = "CC6.1 - CC6.3: Logical Access Controls"
  description = "Verifies MFA enforcement, member invite hygiene, API token expiration and IP conditions, and Zero Trust Access policies."

  children = [
    control.account_enforce_twofactor,
    control.user_mfa_enabled,
    control.account_member_accepted_and_mfa,
    control.api_token_expiration_set,
    control.api_token_ip_condition,
    control.access_policy_no_unrestricted_bypass
  ]

  tags = merge(local.common_tags, {
    framework = "soc2"
    criteria  = "CC6.1"
  })
}

benchmark "soc2_cc6_boundary_and_transmission" {
  title       = "CC6.6 - CC6.7: Boundary Protection & Transmission Confidentiality"
  description = "Verifies TLS 1.2+/1.3, Strict SSL, HSTS, WAF, browser integrity checks, DNSSEC, CAA, SPF/DMARC, and proxied edge endpoints."

  children = [
